#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for OpenMP pragmas (ignored if compiled without -fopenmp). */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* -------------------------------------------------------------------------
 * Tunable blocking factors for the main kernel.
 *
 * These control the i- and j-dimension tile sizes used to improve cache
 * locality.  They can be overridden at compile time, e.g.:
 *
 *   gcc -DFLOYD_BLOCK_I=64 -DFLOYD_BLOCK_J=64 ...
 * ------------------------------------------------------------------------- */
#ifndef FLOYD_BLOCK_I
#  define FLOYD_BLOCK_I 32
#endif

#ifndef FLOYD_BLOCK_J
#  define FLOYD_BLOCK_J 32
#endif


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Use PolyBench's runtime loop bound. */
  const int nn = _PB_N;

  /* Temporary buffers holding a snapshot of the k-th row and column.
   *
   * Rationale:
   *  - In the original Floyd–Warshall, for each k we repeatedly access
   *    path[i][k] and path[k][j].
   *  - Copying them into contiguous temporary buffers improves locality
   *    and allows safe OpenMP parallelization of the i/j loops without
   *    data races (no concurrent read/write on the same matrix entries).
   *
   * Memory overhead is O(n) versus the O(n^2) main matrix, i.e. well
   * below the allowed 50% extra memory.
   */
  DATA_TYPE row_k[nn];
  DATA_TYPE col_k[nn];

#pragma scop
  for (k = 0; k < nn; k++)
    {
      /* Snapshot k-th row (contiguous in memory, cache-friendly). */
      for (j = 0; j < nn; j++)
        row_k[j] = path[k][j];

      /* Snapshot k-th column (strided access, but only once per k). */
      for (i = 0; i < nn; i++)
        col_k[i] = path[i][k];

      /* Parallelized and blocked update over i and j.
       *
       * For each fixed k:
       *   path[i][j] = min(path[i][j], col_k[i] + row_k[j]);
       *
       * Using row_k/col_k guarantees that all threads see consistent
       * values for path[*][k] and path[k][*], matching the sequential
       * algorithm on this benchmark's positive edge weights.
       */
#pragma omp parallel for private(i, j) schedule(static)
      for (int ii = 0; ii < nn; ii += FLOYD_BLOCK_I)
      {
        const int i_end = (ii + FLOYD_BLOCK_I < nn) ? (ii + FLOYD_BLOCK_I) : nn;

        for (int jj = 0; jj < nn; jj += FLOYD_BLOCK_J)
        {
          const int j_end = (jj + FLOYD_BLOCK_J < nn) ? (jj + FLOYD_BLOCK_J) : nn;

          for (i = ii; i < i_end; ++i)
          {
            const DATA_TYPE col_i_k = col_k[i];       /* path[i][k] cached. */
            DATA_TYPE * restrict path_i = path[i];    /* Pointer to row i. */

            /* Inner-most loop over j is contiguous and vectorizable. */
#pragma omp simd
            for (j = jj; j < j_end; ++j)
            {
              const DATA_TYPE via_k = col_i_k + row_k[j]; /* path[i][k] + path[k][j] */
              const DATA_TYPE old   = path_i[j];

              if (via_k < old)
                path_i[j] = via_k;
            }
          }
        }
      }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
