/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimized version:
 *   - For each k, we first take a snapshot of the k-th row and k-th column
 *     into two temporary 1D arrays (row_k and col_k). This removes the
 *     original strided accesses to path[i][k] (column) and allows all
 *     subsequent updates for this k to use only contiguous data.
 *   - Using these snapshots ensures that each update of path[i][j] depends
 *     only on:
 *         * the value of path[i][j] at the start of the k-iteration, and
 *         * the pre-copied path[i][k] and path[k][j],
 *     exactly matching the Floyd–Warshall recurrence.
 *   - Once row_k and col_k are fixed for a given k, all (i,j) pairs are
 *     independent and can be safely parallelized and vectorized.
 *   - The extra memory used is O(2N) DATA_TYPE elements, well within the
 *     50% overhead guideline.
 */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Effective problem size for the kernel (PolyBench may use either
     the compile-time constant N or the runtime parameter n). */
  const int n_eff = _PB_N;

  /* Temporary buffers holding the k-th row and column.
     They are allocated once and reused for every k. */
  DATA_TYPE row_k[n_eff];
  DATA_TYPE col_k[n_eff];

#pragma scop
  for (k = 0; k < n_eff; k++)
    {
      /* ------------------------------------------------------------------
       * 1. Snapshot k-th row and column
       *    This captures the values from the beginning of this k-iteration.
       *    All subsequent computations for this k will use only these
       *    temporaries, which guarantees that the semantics match the
       *    original Floyd–Warshall update:
       *
       *      path[i][j] = min(path[i][j],
       *                       path[i][k] + path[k][j]);
       *
       *    with path[i][k] and path[k][j] taken from the previous
       *    (k-1)-iteration.
       * ------------------------------------------------------------------ */
      for (j = 0; j < n_eff; j++)
        row_k[j] = path[k][j];

      for (i = 0; i < n_eff; i++)
        col_k[i] = path[i][k];

      /* ------------------------------------------------------------------
       * 2. Main relaxation loop
       *
       *    Using the snapshots, the update for each (i,j) is:
       *
       *      via      = col_k[i] + row_k[j];
       *      path[i][j] = min(path[i][j], via);
       *
       *    Each (i,j) pair writes a distinct element of path and only reads
       *    from row_k and col_k, so there are no loop-carried dependencies
       *    inside the i/j loops. This exposes:
       *      - Good spatial locality for path (row-major access).
       *      - Good spatial locality for row_k and col_k (1D arrays).
       *      - Safe parallelism across i (rows).
       *
       *    The OpenMP pragma is purely an optimization hint: if compiled
       *    without OpenMP support, it is ignored and the code runs
       *    sequentially with identical semantics.
       * ------------------------------------------------------------------ */
#pragma omp parallel for private(i,j) schedule(static) if (n_eff >= 32)
      for (i = 0; i < n_eff; i++)
        {
          /* Value of path[i][k] captured at the start of this k-iteration. */
          DATA_TYPE dik = col_k[i];

          /* Row pointer to improve locality and help the compiler
             generate efficient code. */
          DATA_TYPE *restrict path_i = path[i];

          for (j = 0; j < n_eff; j++)
            {
              DATA_TYPE via     = dik + row_k[j];
              DATA_TYPE current = path_i[j];
              path_i[j] = current < via ? current : via;
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
