static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
                           DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  /* Keep declarations for compatibility with the original style. */
  int i, j, k;

  /* _PB_N is the PolyBench “effective” problem size; it may differ from
   * the compile-time constant N when using reduced-size runs. The
   * original kernel used _PB_N in all loops, so we keep that behavior.
   */
  const int n_local = _PB_N;

#pragma scop
  /* One parallel region for the entire kernel to amortize thread
   * creation. Threads cooperate on the 'i' loop for each fixed 'k'.
   * The implicit barrier at the end of '#pragma omp for' is essential
   * to preserve the Floyd–Warshall dependence on k.
   *
   * If the code is compiled without OpenMP support, these pragmas are
   * ignored and execution remains sequential, preserving semantics.
   */
#pragma omp parallel private(i,j,k)
  {
    for (k = 0; k < n_local; ++k)
    {
      /* Pointer to k-th row: reused across all i/j work for this k. */
      DATA_TYPE* pk = path[k];

      /* Distribute rows i across threads for this fixed k. */
#pragma omp for schedule(static)
      for (i = 0; i < n_local; ++i)
      {
        DATA_TYPE* pi = path[i];
        /* Column element path[i][k] is constant across all j for
         * fixed (i, k); hoist it out of the j-loop.
         */
        const DATA_TYPE pik = pi[k];

        /* Block the j-loop to improve cache locality on pi and pk. */
        for (int jj = 0; jj < n_local; jj += FW_BLOCK_SIZE)
        {
          int j_end = jj + FW_BLOCK_SIZE;
          if (j_end > n_local)
            j_end = n_local;

          /* Hint to the compiler: iterations in j have no dependencies,
           * which helps auto-vectorization on GCC.
           */
#pragma GCC ivdep
          for (j = jj; j < j_end; ++j)
          {
            const DATA_TYPE via_k = pik + pk[j];
            if (via_k < pi[j])
              pi[j] = via_k;
          }
        }
      }
      /* Implicit barrier here (end of omp for) ensures all updates for
       * this k are complete before any thread proceeds to k+1.
       */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
