}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Introduce a local restrict-qualified pointer to the 2D array to
     give the compiler stronger aliasing guarantees.
   - Hoist invariant loads (path[i][k]) out of the innermost loop.
   - Use row pointers (row_i, row_k) to improve cache locality and
     enable more straightforward vectorization.
   - Add an OpenMP parallel-for over the i-loop (for each fixed k),
     which is safe since each (i,j) pair is updated exactly once.
   - Add a GCC 'ivdep' pragma on the j-loop to encourage vectorization.
   All these transformations are semantics-preserving for this kernel.
*/
static
void kernel_floyd_warshall [[gnu::flatten, gnu::noinline]] (int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* _PB_N is the (possibly adjusted) problem size used by PolyBench. */
  const int n_pb = _PB_N;

  /* Create a local restrict-qualified view of the 2D array.
     This tells the compiler that 'p' is the only pointer used to
     access this storage in this function, enabling better
     optimization and vectorization. */
  DATA_TYPE (* restrict p)[n] = path;

#pragma scop
  for (k = 0; k < n_pb; k++)
    {
      /* Pointer to row k: reused for all (i,j) at this k. */
      DATA_TYPE * restrict row_k = p[k];

      /* Parallelize across rows i for this fixed k.
         - Different (i,j) pairs are independent.
         - No loop-carried dependencies across different i.
         - Each element p[i][j] is written exactly once per k. */
#pragma omp parallel for private(j) schedule(static) if (n_pb >= 64)
      for (i = 0; i < n_pb; i++)
      {
        /* Pointer to current row i. */
        DATA_TYPE * restrict row_i = p[i];

        /* Value path[i][k] is invariant across the j-loop;
           load it once here to avoid redundant memory accesses. */
        const DATA_TYPE pik = row_i[k];

        /* The inner-most loop has no loop-carried dependencies:
           each iteration only reads/writes row_i[j] and row_k[j].
           Using GCC ivdep helps the compiler vectorize the loop
           aggressively even in the presence of potential aliasing. */
#pragma GCC ivdep
        for (j = 0; j < n_pb; j++)
        {
          const DATA_TYPE via = pik + row_k[j];
          const DATA_TYPE dij = row_i[j];

          /* This is exactly:
               path[i][j] = path[i][j] < path[i][k] + path[k][j]
                            ? path[i][j]
                            : path[i][k] + path[k][j];
             written using local temporaries to avoid recomputing
             the sum and to give the compiler a clearer pattern. */
          row_i[j] = (dij < via) ? dij : via;
        }
      }
    }
#pragma endscop

}


